Sharing a workaround for my issue:

```javascript
export default defineConfig({
  build: {
    rollupOptions: {
      input: {
        app: "template.html",
      },
    },
  },
  plugins: [
    {
      name: "add-data-preload-attr",
      transformIndexHtml(html) {
        return html.replace(
          new RegExp('rel="stylesheet"', "g"),
          'rel="stylesheet" data-preload="true"'
        );
      },
    },
  ],
});
```

